/* ── 多國語言 ──────────────────────────────────────────────
 * 這個檔放在每頁 <head>，比 app.js 早載入。
 * 語言：網址 ?lang=en（或 zh、ko、ja）＞ 上次選的（瀏覽器記住）＞ 中文。
 * 翻譯表：下面的 _t.add({...})，中文原文當索引，後面接 en、ko、ja。
 *   - 頁面上寫死的中文（標題、說明）：整段（含 <code> 等標籤）當索引。
 *   - 程式裡的中文：寫成 _t('中文')；有數字要插入的寫成 _t('第 {0} 格', n)。
 *   - 找不到翻譯就顯示中文，不會壞掉。
 * data/*.js 裡的說明文字翻譯放在各自的 data 檔（CD_T）。
 */
(function () {
  var LANGS = ['zh', 'en', 'ko', 'ja'], HTML_LANG = { zh: 'zh-TW', en: 'en', ko: 'ko', ja: 'ja' };
  var m = /[?&]lang=(zh|en|ko|ja)\b/.exec(location.search), lang = m ? m[1] : null;
  if (!lang) { try { lang = localStorage.getItem('cd-lang'); } catch (e) { } }
  if (LANGS.indexOf(lang) < 0) lang = 'zh';
  if (m) { try { localStorage.setItem('cd-lang', lang); } catch (e) { } }
  document.documentElement.lang = HTML_LANG[lang];

  var D = {};
  function t(s) {
    var e = lang !== 'zh' && D[s], r = e && e[lang] != null ? e[lang] : s;
    for (var i = 1; i < arguments.length; i++) r = r.split('{' + (i - 1) + '}').join(arguments[i]);
    return r;
  }
  t.lang = lang; t.langs = LANGS;
  t.add = function (o) { for (var k in o) D[k] = o[k]; };
  t.has = function (s) { return !!D[s]; };

  // 頁面上寫死的文字：找出含中文的最小區塊（遇到粗體、code 這類行內標籤會往外找），整段換掉
  var INLINE = { STRONG: 1, B: 1, CODE: 1, EM: 1, I: 1, SMALL: 1, BR: 1, MARK: 1, U: 1, S: 1, SUB: 1, SUP: 1 };
  var SKIP = { SCRIPT: 1, STYLE: 1, TEXTAREA: 1 };
  var CJK = /[㐀-鿿　-〿＀-￯]/;
  var norm = function (h) { return h.replace(/\s+/g, ' ').trim(); };
  function units(root) {
    var list = [], seen = [], w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT), n;
    while ((n = w.nextNode())) {
      if (!CJK.test(n.nodeValue)) continue;
      var el = n.parentNode, bad = false;
      for (var p = el; p && p !== root; p = p.parentNode) if (SKIP[p.tagName]) bad = true;
      if (bad) continue;
      while (INLINE[el.tagName] && el.parentNode && el.parentNode !== root) el = el.parentNode;
      if (seen.indexOf(el) < 0) { seen.push(el); list.push(el); }
    }
    return list.filter(function (el) { for (var p = el.parentNode; p; p = p.parentNode) if (seen.indexOf(p) >= 0) return false; return true; });
  }
  var ATTRS = ['placeholder', 'title', 'aria-label'];
  function attrs(root) {
    var out = [];
    root.querySelectorAll('[placeholder],[title],[aria-label]').forEach(function (el) {
      ATTRS.forEach(function (a) { var v = el.getAttribute(a); if (v && CJK.test(v)) out.push([el, a]); });
    });
    return out;
  }
  t.units = units; t.attrs = attrs; t.norm = norm;
  t.page = function (root) {
    if (lang === 'zh') return;
    root = root || document.body;
    units(root).forEach(function (el) { var k = norm(el.innerHTML); if (D[k] && D[k][lang] != null) el.innerHTML = D[k][lang]; });
    attrs(root).forEach(function (x) { var v = x[0].getAttribute(x[1]); if (D[v] && D[v][lang] != null) x[0].setAttribute(x[1], D[v][lang]); });
    if (D[document.title] && D[document.title][lang]) document.title = D[document.title][lang];
  };
  window._t = t;
})();

